export const totalKm=(r)=>r.legs.reduce((s,l)=>s+Number(l.km),0)*(r.round?2:1);
export const calculate=(km,consumption,price,fee,compensation)=>{const liters=km*consumption/100,cost=liters*price;return{km,liters,cost,due:fee+(compensation?cost:0),net:fee+(compensation?cost:0)-cost}};
export function validData(d){const num=(n,max=1e9)=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=max;const str=s=>typeof s==='string'&&s.length<=2000;const route=r=>r&&str(r.start)&&r.start.trim()&&typeof r.round==='boolean'&&Array.isArray(r.legs)&&r.legs.length>0&&r.legs.length<=30&&r.legs.every(l=>str(l.to)&&l.to.trim()&&num(l.km,100000)&&l.km>0);return d&&d.version===1&&Array.isArray(d.cars)&&Array.isArray(d.routes)&&Array.isArray(d.trips)&&[d.cars,d.routes,d.trips].every(a=>a.length<=10000)&&d.cars.every(c=>str(c.id)&&str(c.name)&&num(c.consumption,100)&&c.consumption>0)&&d.routes.every(r=>str(r.id)&&route(r))&&d.trips.every(t=>str(t.id)&&route(t.route)&&/^\d{4}-\d{2}-\d{2}$/.test(t.date)&&str(t.carName)&&num(t.consumption,100)&&t.consumption>0&&num(t.price,1000)&&num(t.fee)&&typeof t.compensation==='boolean'&&typeof t.paid==='boolean'&&str(t.note))&&d.settings&&num(d.settings.price,1000)}
